import {PHASES,FACTS,ROLES,VARIANTS,VERDICT_FIELDS} from './content.js';
import {analyse,MANUAL,formCheck,SOURCES} from './argumentation.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let context,model,key,timer;
export const QUESTIONS=[
 ['certainty','War sicher, dass alle ohne Abschuss sterben würden?',[['yes','Ja, das stand fest.'],['open','Der weitere Verlauf ist unbekannt.'],['no','Nein, sie wären sicher gerettet worden.']],'open','Weder Tod noch Rettung stehen sicher fest. Der Cockpitversuch beweist keinen sicheren Ausgang. F06–F07, PDF-S. 51–52 und 68–71.'],
 ['knowledge','Kannte Koch die SMS an Meiser bei seiner Entscheidung?',[['yes','Ja.'],['no','Im Textfall ist das nicht sein damaliges Wissen.']],'no','Später bekannte Informationen nicht rückwirkend zuschreiben. F05–F06, PDF-S. 51–52 und 68–71. In der Variante „Nachricht an Koch“ erhält er ausdrücklich zusätzliche Informationen über den Cockpitversuch.'],
 ['permission','Sind „rechtlich erlaubt“ und „persönlich entschuldigt“ dasselbe?',[['yes','Ja.'],['no','Nein: eine verbotene Tat kann die Frage einer Entschuldigung aufwerfen.']],'no','Rechtfertigung betrifft die Rechtswidrigkeit, Entschuldigung die persönliche Schuld. StGB §§ 34–35; Dramentext PDF-S. 82, 88–93.']
];
const PHASE_QUESTIONS=[['Welche Fakten stehen fest?','Welche Unterschiede zwischen eurer Rolle und euch selbst sind wichtig?'],['Ich eröffne die Verhandlung. Herr Koch, Sie dürfen sich äussern oder schweigen.','Wir unterscheiden Tatsachen, Vermutungen und Bewertungen.'],['Welches Delikt werfen Sie Koch vor?','Welcher Beleg soll welches Tatbestandsmerkmal tragen?'],['Welche Informationen hatten Sie vor dem Abschuss?','Welche anderen Handlungsmöglichkeiten haben Sie geprüft?'],['Welcher Befehl wurde Koch übermittelt?','Was haben Sie selbst wahrgenommen, was erst später erfahren?'],['Was genau ging aus der SMS hervor?','Was wissen Sie über den Ausgang des Cockpitversuchs?'],['Was ist Ihr stärkster Rechtsgrund?','Wie antworten Sie auf den stärksten Einwand der Gegenseite?'],['Warum soll die Ausnahmesituation den persönlichen Schuldvorwurf verändern?','Wie begrenzen Sie Ihre Argumentation auf diesen Fall?'],['Herr Koch, möchten Sie abschliessend noch etwas sagen?'],['Welche Feststellung trägt unser Urteil?','Welchen Zweifel konnten wir nicht auflösen?'],['Was hat euch überzeugt?','Was würdet ihr nach dem Perspektivwechsel anders beurteilen?']];
function load(){try{return JSON.parse(sessionStorage.getItem(key))||{step:0,answers:{},notes:{},evidence:{}};}catch{return {step:0,answers:{},notes:{},evidence:{}};}}
function save(){try{sessionStorage.setItem(key,JSON.stringify(model));}catch{context.announce('Speichern nicht möglich. Sichere deinen Text vor dem Schliessen.');}}
export function mountAssistant(root,ctx){context=ctx;key='terror-guide-'+ctx.session.code;model=load();draw(root);}
export function phasePrompts(phase){return PHASE_QUESTIONS[phase]||PHASE_QUESTIONS[0];}
export function makeDraft(m,room){const n=m.notes,e=Object.entries(m.evidence).map(([id,x])=>`Beitrag #${id} (${x.status}): ${x.text}`).join('\n');return {tenor:n.tenor||'',facts:`Fall: ${VARIANTS[room.variant].name}. ${n.facts||''}`,evidence:`${e}\nBeweiswürdigung: ${n.evidence||''}`.slice(0,1200),offence:n.offence||'',justification:n.justification||'',excuse:n.excuse||'',counter:n.counter||'',reasons:n.reasons||''};}
function note(id,label,help){return `<label for="guide-${id}">${label}</label><p class="source">${help}</p><textarea id="guide-${id}" data-guide-note="${id}" maxlength="900">${esc(model.notes[id]||'')}</textarea>`;}
function draw(root){const ctx=context,room=ctx.getRoom(),step=model.step||0;root.innerHTML=`<div class="callout"><b>Begleiteter Gerichtsassistent</b><p>Eine Frage nach der anderen. Deine Auswahl und Belegnotizen bleiben in diesem Fenster. Du entscheidest; der Assistent stellt Rückfragen.</p></div><div class="guide-progress">${['Leiten','Belege','Fakten','Recht','Schuld','Gegenprüfung','Entwurf'].map((x,i)=>`<button data-step="${i}" class="${i===step?'primary':'secondary'}" aria-current="${i===step?'step':'false'}">${i+1} ${x}</button>`).join('')}</div><div id="guide-body"></div>`;const body=root.querySelector('#guide-body');
 if(!room){body.innerHTML='<p>Warte auf die Verbindung zum Raum.</p>';return;}
 if(step===0)body.innerHTML=`<h3>Die Verhandlung führen</h3><p>Aktuell: <b>${esc(PHASES[room.phase][0])}</b></p><p>${esc(PHASES[room.phase][1])}</p><p>Diese Fragen kannst du bearbeiten und anschliessend im Chat senden:</p>${phasePrompts(room.phase).map(q=>`<button class="question-card" data-question="${esc(q)}">${esc(q)}</button>`).join('')}<div class="callout">Lass die Gegenseite antworten. Frage bei Behauptungen: „Woran machst du das fest?“ Erteile links das passende Rederecht. Koch erhält vor der Beratung das letzte Wort.</div><button data-step="1">Belege sammeln →</button>`;
 if(step===1){const messages=room.messages.filter(e=>['aussage','frage','einwand'].includes(e.kind));body.innerHTML='<h3>Was wurde tatsächlich gesagt?</h3><p>Speichere Beiträge mit „Als Beleg merken“ im Chat. Eine Aussage ist dadurch noch nicht bewiesen. Ordne sie ein und begründe unten ihre Bedeutung.</p>'+Object.entries(model.evidence).map(([id,e])=>`<article class="evidence-card"><b>Beitrag #${id} · ${esc(e.role)}</b><blockquote>${esc(e.text)}</blockquote><label>Status<select data-evidence-status="${id}">${['offen','gesichert','umstritten'].map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select></label><button data-remove-evidence="${id}">Aus Merkliste entfernen</button></article>`).join('')+(messages.length?'':'<p>Noch keine Aussagen im Chat. Die Fallkarten findest du im Reiter „Fakten“.</p>')+note('evidence','Was zeigen die Belege – und was nicht?','„Beitrag #… stützt …, weil … Ein Zweifel bleibt …“ Ergänze gegebenenfalls F01–F12 oder PDF-Seiten.')+'<button data-step="2">Fakten klären →</button>';}
 if(step===2)body.innerHTML='<h3>Wissen oder Vermutung?</h3>'+QUESTIONS.slice(0,2).map(questionHTML).join('')+note('facts','Was hältst du für erwiesen?','Nenne Handlung, Folgen, Befehl und die ausdrücklich gewählte Fallvariante. „Im Text ist belegt … Unklar bleibt …“')+'<button data-step="3">Recht prüfen →</button>';
 if(step===3)body.innerHTML='<h3>Was wird rechtlich geprüft?</h3><p><b>Tatbestand:</b> Passt das Geschehen zu den Merkmalen einer Strafnorm? Für Mord muss ein zusätzliches Mordmerkmal begründet werden.</p>'+note('offence','Welche Merkmale siehst du als erfüllt?','„Wir prüfen § 212 StGB. Für § 211 müsste zusätzlich … belegt sein.“ Öffne die Normen im Reiter Recht.')+questionHTML(QUESTIONS[2])+'<p><b>Rechtfertigung:</b> War die Handlung ausnahmsweise erlaubt? Eine grössere Zahl bedrohter Menschen allein beantwortet diese Frage nicht.</p>'+note('justification','Warum war die Tat erlaubt oder nicht erlaubt?','Prüfe Unbeteiligte, Menschenwürde und erreichbare Alternativen. Nutze GG Art. 1–2 und StGB §§ 32, 34.')+'<button data-step="4">Persönliche Schuld →</button>';
 if(step===4)body.innerHTML='<h3>Was konnte man Koch persönlich zumuten?</h3><p>Eine verbotene Tat und persönliche Entschuldigung sind verschiedene Fragen. § 35 hat enge Voraussetzungen: unter anderem eine Gefahr für die handelnde Person, Angehörige oder nahestehende Personen. Eine Ausnahme ausserhalb des Gesetzes ist umstritten.</p>'+note('excuse','Was spricht für oder gegen eine Entschuldigung?','„Für Koch spricht … Dagegen spricht … § 35 passt / passt nicht, weil …“ Prüfe auch Wissen, Irrtümer und die Grenze deiner Begründung.')+'<button data-step="5">Gegenargument prüfen →</button>';
 if(step===5)body.innerHTML='<h3>Prüfe die stärkste Gegenseite</h3><label for="guide-direction">Wozu tendierst du?</label><select id="guide-direction" data-guide-note="direction"><option value="">Noch keine Wahl</option>'+['Freispruch','Verurteilung','Noch offen'].map(v=>`<option ${model.notes.direction===v?'selected':''}>${v}</option>`).join('')+'</select><div id="counter-prompt" class="callout">'+counterPrompt()+'</div>'+note('counter','Was ist der stärkste Einwand – und deine Antwort?','Gib die Gegenposition fair wieder. Ein blosses „Das sehe ich anders“ reicht nicht.')+note('reasons','Welcher Grund entscheidet für dich?','„Trotz dieses Einwands entscheidet …, weil … Dieser Grund gilt nur, wenn …“')+'<button data-step="6">Urteilsentwurf →</button>';
 if(step===6)body.innerHTML='<h3>Dein begründetes Urteil</h3>'+note('tenor','Wie lautet deine Entscheidung?','„Lars Koch wird …“ Nenne bei einer Verurteilung das Delikt. Ist dein Urteil noch offen, kehre zur Beweisaufnahme zurück.')+'<p>Der Entwurf verwendet deine eigenen Antworten und ausgewählten Belege. Es werden keine fehlenden Gründe erfunden.</p><button id="assemble" class="primary">Entwurf zusammensetzen und bearbeiten</button><div id="assemble-status" role="status"></div>';
 root.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step!==undefined){model.step=Number(b.dataset.step);save();draw(root);}if(b.dataset.question)ctx.cite(b.dataset.question);if(b.dataset.removeEvidence){delete model.evidence[b.dataset.removeEvidence];save();draw(root);}if(b.id==='assemble'){if(!['Freispruch','Verurteilung'].includes(model.notes.direction)){root.querySelector('#assemble-status').textContent='Deine Entscheidung ist noch offen. Bearbeite in Schritt 6 die Gegenprüfung und entscheide dich dort ausdrücklich – oder kehre zur Beweisaufnahme zurück.';return;}const missing=['tenor','facts','evidence','offence','justification','excuse','counter','reasons'].filter(k=>(model.notes[k]||'').trim().length<15);if(missing.length){root.querySelector('#assemble-status').textContent='Ergänze noch: '+missing.map(k=>VERDICT_FIELDS.find(f=>f[0]===k)?.[1]||k).join(', ')+'. Je Feld mindestens ein eigener begründeter Satz.';return;}ctx.useDraft(makeDraft(model,room));}};
 root.oninput=e=>{if(e.target.dataset.guideNote){model.notes[e.target.dataset.guideNote]=e.target.value;save();}};
 root.onchange=e=>{if(e.target.dataset.questionId){model.answers[e.target.dataset.questionId]=e.target.value;save();const q=QUESTIONS.find(q=>q[0]===e.target.dataset.questionId);root.querySelector('#answer-'+q[0]).textContent=questionFeedback(q,e.target.value);}if(e.target.dataset.evidenceStatus){model.evidence[e.target.dataset.evidenceStatus].status=e.target.value;save();}if(e.target.id==='guide-direction'){model.notes.direction=e.target.value;save();root.querySelector('#counter-prompt').textContent=counterPrompt();}};
}
function counterPrompt(){return model.notes.direction==='Freispruch'?'Prüfe Nelsons stärksten Einwand: Welche Grenze schützt die Unbeteiligten, wenn Rettungsabsicht entschuldigt?':model.notes.direction==='Verurteilung'?'Prüfe Bieglers stärksten Einwand: Wie berücksichtigst du die Ausnahmesituation und Kochs persönlichen Schuldvorwurf?':'Welche zusätzliche Information oder Rechtsfrage hindert dich an einer Entscheidung? Was könnte jede Seite gegen deine bisherige Begründung einwenden?';}
export function questionFeedback(q,value){return (value===q[3]?'Diese Unterscheidung passt zum Textfall. ':'Noch einmal prüfen: ')+q[4];}
function questionHTML(q){return `<fieldset><legend>${esc(q[1])}</legend>${q[2].map(([v,label])=>`<label class="check"><input type="radio" name="${q[0]}" data-question-id="${q[0]}" value="${v}" ${model.answers[q[0]]===v?'checked':''}>${esc(label)}</label>`).join('')}<p id="answer-${q[0]}" class="callout" aria-live="polite">${model.answers[q[0]]?esc(questionFeedback(q,model.answers[q[0]])):'Wähle eine Antwort. Du erhältst sofort einen begründeten Hinweis.'}</p></fieldset>`;}
export function rememberEvidence(message,session){const k='terror-guide-'+session.code;let m;try{m=JSON.parse(sessionStorage.getItem(k))||{step:1,answers:{},notes:{},evidence:{}};}catch{m={step:1,answers:{},notes:{},evidence:{}};}m.evidence[message.id]={text:message.text.slice(0,600),role:ROLES[message.role]?.name||message.role,status:'offen'};m.step=1;sessionStorage.setItem(k,JSON.stringify(m));}
export function renderAnalysis(text){const a=analyse(text);return `<p class="source">Lokaler Sprachabgleich, keine Note. Treffer sind Prüfanlässe; fehlende Treffer beweisen keinen Mangel.</p><h3>Argumentstruktur</h3><ul>${a.structure.map(x=>`<li>${x.label}: ${x.found?'sprachliches Signal gefunden – Funktion selbst prüfen':'nicht eindeutig erkannt – prüfe selbst'}</li>`).join('')}</ul><h3>Mögliche Prüfstellen</h3>${a.flags.length?a.flags.map(f=>`<article class="evidence-card"><b>${esc(f.title)}</b><blockquote>${esc(f.excerpt)}</blockquote>${f.reported?'<p>Zitat, Verneinung oder berichtete Position möglich: Ordne die Aussage zuerst ihrer Sprecherrolle zu. Kein Fehlernachweis.</p>':''}<p>${esc(f.question)}</p><p class="source">${esc(f.source)}</p></article>`).join(''):'<p>Keine hinterlegten Muster erkannt. Das ist keine Bestätigung, dass der Text fehlerfrei ist. Nutze die manuellen Prüffragen.</p>'}`;}
export function mountArguments(root,text='',onChange=()=>{}){root.innerHTML='<h3>Argumente gemeinsam genauer lesen</h3><p>These → Grund → Beleg → Schluss. Welche unausgesprochene Regel verbindet Grund und Schluss?</p><label for="argument-text">Ein Beitrag oder dein eigener Entwurf</label><textarea id="argument-text" maxlength="12000" placeholder="Beitrag einfügen oder im Chat „Argument prüfen“ wählen …">'+esc(text)+'</textarea><button id="argument-check">Argument prüfen</button><div id="argument-result" aria-live="polite"></div><details><summary>Weitere Denkfehler selbst prüfen</summary>'+MANUAL.map(([t,q,s])=>`<h3>${esc(t)}</h3><p>${esc(q)}</p><p class="source">Argumentationslehre ${s}</p>`).join('')+'</details><details><summary>Logik-Werkstatt: Folgt der Schluss?</summary><p>Wir nehmen an: Wenn A, dann B. Beispiel: Wenn der Alarm ausgelöst wird, leuchtet die Lampe. Eine andere Ursache für die Lampe ist damit nicht ausgeschlossen.</p><label>Zusätzlich gilt<select id="logic-premise"><option value="a">A</option><option value="b">B</option><option value="nota">nicht A</option><option value="notb">nicht B</option></select></label><label>Behaupteter Schluss<select id="logic-conclusion"><option value="b">B</option><option value="a">A</option><option value="nota">nicht A</option><option value="notb">nicht B</option></select></label><button id="logic-check">Schluss prüfen</button><p id="logic-result" aria-live="polite"></p><p>Deduktion: Folgt etwas notwendig aus den Prämissen? Induktion: Wie gut trägt eine Verallgemeinerung? Abduktion: Welche Erklärung passt am besten? Analogie: Ist die entscheidende Gemeinsamkeit vorhanden? Die letzten drei liefern keine logische Gewissheit.</p></details><p class="source">'+esc(SOURCES)+' <a href="https://github.com/PatrickFischerKSA/argumentationspruefer" target="_blank" rel="noopener">Quellen-Repository ↗</a></p>';
 const run=()=>{const input=root.querySelector('#argument-text'),result=root.querySelector('#argument-result');if(input&&result)result.innerHTML=renderAnalysis(input.value);};root.querySelector('#argument-check').onclick=run;root.querySelector('#argument-text').oninput=e=>{onChange(e.target.value);clearTimeout(timer);timer=setTimeout(run,650);};root.querySelector('#logic-check').onclick=()=>root.querySelector('#logic-result').textContent=formCheck(root.querySelector('#logic-premise').value,root.querySelector('#logic-conclusion').value);if(text)run();}

export function refreshAssistant(root){if(root&&model?.step===0)draw(root);}
